package main

import (
	"fmt"
	"os/exec"
	"syscall"
)

func alushi() string {
	komanda := exec.Command("powershell.exe", "-enc", "")
	komanda.SysProcAttr = &syscall.SysProcAttr{
		HideWindow: true,
	}

	kmdoutput, err := komanda.CombinedOutput()
	if err != nil {
		fmt.Println("err:", err)
	}

	return string(kmdoutput)
}

func main() {
	fmt.Println("testing shit out")
	callResult := alushi()
	fmt.Println("output:", callResult)
}
